How can I implement a smart caching strategy that decides whether to fetch data from the cache or make a new request based on usage patterns?

To implement a smart caching strategy, you can use an LRU (Least Recently Used) eviction policy along with hit/miss tracking. Below is a code snippet that modifies the `CacheManager` to include this logic:

```python
class CacheManager:
    def __init__(self, max_size):
        self.cache = {}  # Dictionary for storing cached data
        self.access_order = []  # List to track access order
        self.max_size = max_size

    def get(self, key):
        if key in self.cache:
            self.access_order.remove(key)  # Update access order
            self.access_order.append(key)
            return self.cache[key]  # Cache hit
        else:
            return None  # Cache miss

    def put(self, key, value):
        if key not in self.cache:
            if len(self.cache) >= self.max_size:
                oldest_key = self.access_order.pop(0)  # Remove least recently used item
                del self.cache[oldest_key]
            self.cache[key] = value  # Add new item
            self.access_order.append(key)

    def fetch_data(self, key):
        cached_value = self.get(key)
        if cached_value:
            return cached_value  # Return cached value
        else:
            data = self.make_external_request(key)  # Simulate a data fetch
            self.put(key, data)
            return data

    def make_external_request(self, key):
        # Simulate an external data fetch
        return f'Data for {key}'
```

