function deployWithRetry(deployment, retries = 3) {
    let attempts = 0;
    let success = false;

    while (attempts < retries && !success) {
        try {
            success = deploy(deployment); // Assume deploy is a function that returns true on success
            if (!success) throw new Error('Deployment failed');
        } catch (error) {
